package com.aistock.scheduler.task;
import java.time.*;import java.net.*;import java.util.*;import com.fasterxml.jackson.databind.*;import com.sun.net.httpserver.HttpServer;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class RevisionClientTest {
 final ObjectMapper mapper=new ObjectMapper().findAndRegisterModules();
 @Test void exactIdentityPathsAndEmptyPages()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);String raw=UUID.randomUUID().toString();server.createContext("/internal/v1/",ex->{assertEquals("private",ex.getRequestHeaders().getFirst("X-Service-Token"));var n=mapper.createObjectNode().put("code","OK");var d=n.putObject("data");if(ex.getRequestURI().getPath().endsWith("revision-events")){assertEquals("after=7&limit=1",ex.getRequestURI().getQuery());d.putArray("items").addObject().put("eventId",8).put("instrumentId","SH600030").put("rawVersionId",raw);}else{assertTrue(ex.getRequestURI().getQuery().contains("instrumentId=SH600030"));d.put("cutoffDate","2026-10-05").putNull("nextCursor").putArray("items");}var bytes=mapper.writeValueAsBytes(n);ex.sendResponseHeaders(200,bytes.length);ex.getResponseBody().write(bytes);ex.close();});server.start();try{String url="http://127.0.0.1:"+server.getAddress().getPort();var c=new HttpRevisionClient(url,url,"private",mapper);assertEquals(8,c.next(7).eventId());assertTrue(c.affected("SH600030",LocalDate.parse("2026-10-05"),null).items().isEmpty());}finally{server.stop(0);}}
 @Test void wrongEventOrAffectedStockCannotBeAccepted()throws Exception{for(String mode:List.of("old-event","fractional","wrong-stock")){var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/internal/v1/",ex->{var n=mapper.createObjectNode().put("code","OK");var d=n.putObject("data");var a=d.putArray("items").addObject();if(mode.equals("wrong-stock")){d.put("cutoffDate","2026-10-05").putNull("nextCursor");a.put("predictionId",UUID.randomUUID().toString()).put("instrumentId","SZ000002").put("dueThrough","2026-10-05").put("ruleVersion","origin-share-close-v1");}else{a.put("eventId",mode.equals("fractional")?8.5:7).put("instrumentId","SH600030").put("rawVersionId",UUID.randomUUID().toString());}var bytes=mapper.writeValueAsBytes(n);ex.sendResponseHeaders(200,bytes.length);ex.getResponseBody().write(bytes);ex.close();});server.start();try{String url="http://127.0.0.1:"+server.getAddress().getPort();var c=new HttpRevisionClient(url,url,"private",mapper);if(mode.equals("wrong-stock"))assertThrows(RuntimeException.class,()->c.affected("SH600030",LocalDate.parse("2026-10-05"),null));else assertThrows(RuntimeException.class,()->c.next(7));}finally{server.stop(0);}}}
}
